#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""PsychoPy presentation script generated by lexsync.

Design: zh_freqcontrast    Language: chinese
Conditions file: zh_freqcontrast_chinese_psychopy.csv

Each trial is rendered from a declarative list of events (``EVENTS``), so one
interpreter serves every paradigm. Onset triggers are written to the parallel
port on the exact flip on which their stimulus first appears, using
``win.callOnFlip``, the frame-locking that motivates lexsync. Stimulus
text is read as data from the conditions file at run time (never interpolated
into this code). When no parallel-port driver is present (a development machine,
macOS or continuous integration), a mock port prints the codes so the script
still runs end to end with no hardware.

Keys are read from psychopy.hardware.keyboard. A stimulus that collects its own
response (an event with ``respond``) resets the keyboard clock and clears the
keyboard on its onset flip, beside its trigger, so a key pressed while it is on
screen counts and the reaction time runs from its onset. The first key ends the
stimulus. Without one, the screen blanks and the window stays open until the
stimulus's duration and the timeout have passed. A ``response`` event, which a
design keeps with ``from: offset``, opens its window on its own flip, and each
self-paced reading region and each question is timed from the flip that shows it.

Every trial is written to data/<base>_p<participant>_v<version>_<date>-<time>.csv
beside this script, without the _p part when no participant number is given. Each
row holds the run, the trial's fields and trigger codes, the response, its reaction
time in milliseconds, whether the window closed without one and whether the key was
the trial's `answer`, each region's reading time, the question's response and
reaction time, the measured refresh rate, and the flips each event took and the
time of its first, from the trial's first flip. The header is written first and
each row as its trial ends, so a run stopped with escape leaves a valid file of the
trials it completed.

The conditions file holds every presentation version of the design, one per
(replicate, list) pair, and a run presents one of them (``VERSIONS`` lists them).
Launched as ``python <this file> --participant 3``, the script runs that
participant's version, and participant p runs version ((p - 1) mod V) + 1 of the
V versions, the rule lexsync's participant_table() allocates by. ``--version K``,
or ``--list K`` when the versions do not span several replicates, chooses a
version outright. Launched with none of these, the script asks for the
participant number and the version in a dialogue, and a blank version takes the
participant's by the same rule. A version the script does not have stops the run
with a message.

Before the first trial, the script shows the version's instructions
(``INSTRUCTIONS``, one text per version), the design's own text or lexsync's for
its task, and waits for the space bar, which also lets the experimenter start the
run. Escape there ends the run before anything is recorded. The instructions are
read as data, like the stimulus text.

Generated by lexsync; edit the design configuration rather than this file.
"""
import csv
import itertools
import json
import os
import re
import sys
import time

from psychopy import visual, core, parallel
from psychopy.hardware import keyboard

HERE = os.path.dirname(os.path.abspath(__file__))
CONDITIONS_FILE = os.path.join(HERE, "zh_freqcontrast_chinese_psychopy.csv")
# Each run writes its own data file here, named after this experiment.
DATA_DIR = os.path.join(HERE, "data")
DATA_STEM = "zh_freqcontrast_chinese"
TRIGGER_ADDRESS = 0x0378
TRIGGER_HOLD_MS = 50
# A pulse shorter than this may not register on the amplifier at all, so a fast
# display must not be allowed to shorten the hold below it.
MIN_TRIGGER_HOLD_MS = 10
# Whole flips the onset code is held for; set from the measured refresh in main().
TRIGGER_HOLD_FRAMES = 3
INTER_TRIGGER_S = 0.01
FULLSCREEN = False
WORD_FONT = "SimHei"
# Used only if the display's refresh cannot be measured at start-up.
ASSUMED_REFRESH_HZ = 60
# Set from the measured refresh in main(); durations are declared in
# milliseconds and converted to whole flips against it.
REFRESH_HZ = float(ASSUMED_REFRESH_HZ)
BLOCK_START_TRIGGER = 254
BLOCK_END_TRIGGER = 255
# The keyboard every key is read from; created in main().
KEYBOARD = None

# The trial event sequence (declarative data, written by lexsync).
EVENTS = json.loads(r"""[{"type":"fixation","text":"+","ms":500},{"type":"text","field":"word","ms":500,"trigger":"@condition_trigger","respond":{"keys":["left","right"],"timeout":2}},{"type":"blank","ms":250}]""")
# The presentation versions, one per (replicate, list) pair of the conditions file,
# numbered in that order. A run presents one of them.
VERSIONS = json.loads(r"""[{"version":1,"replicate":1,"list":1,"n_trials":160}]""")
# The instructions each version shows before its first trial, in version order. A
# response mapping rotated across lists names each list's keys.
INSTRUCTIONS = json.loads(r"""["When a response is needed, press the left arrow key or the right arrow key. Respond as quickly and accurately as you can."]""")

# The data file's columns. The run and the trial's place in the design lead, the
# trial's other fields follow in the conditions file's order, then its trigger codes
# and its answer, if it has one, and last what the trial recorded.
LEADING_COLUMNS = ["participant", "version", "replicate", "list", "block", "trial", "set",
                   "condition"]
CODE_COLUMNS = ["condition_trigger", "item_trigger", "answer"]
MEASURE_COLUMNS = ["response", "rt_ms", "timed_out", "correct", "region_rts_ms",
                   "question_response", "question_rt_ms", "refresh_hz", "event_flips",
                   "event_onsets_ms"]
# `correct` scores the response, or in a design without a response event, the question.
SCORES_RESPONSE = any(ev["type"] == "response" or "respond" in ev for ev in EVENTS)


class MockPort:
    """Stand-in used when no parallel-port driver is available."""

    def setData(self, data):
        print("[lexsync mock trigger] %d" % int(data))


def open_port(address):
    try:
        port = parallel.ParallelPort(address=address)
        port.setData(0)  # the dummy backend raises NotImplementedError here
        return port
    except Exception:
        return MockPort()


def load_trials(path):
    with open(path, newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def whole(cell):
    """A replicate or list cell as a number. A conditions file without the column is
    one replicate, or one list, numbered 1."""
    if cell is None or str(cell).strip() == "":
        return 1
    return int(float(cell))


def version_rows(trials, version):
    """The rows of one presentation version, in the conditions file's order."""
    wanted = (version["replicate"], version["list"])
    return [t for t in trials if (whole(t.get("replicate")), whole(t.get("list"))) == wanted]


def launch_arguments(argv):
    """--participant N, --version K and --list K from the command line, as given.

    Both ``--version 2`` and ``--version=2`` are read. Arguments the script does not
    know are left alone, for whatever launched it.
    """
    given = {}
    position = 0
    while position < len(argv):
        name, equals, value = argv[position].partition("=")
        if name in ("--participant", "--version", "--list"):
            if not equals:
                if position + 1 >= len(argv):
                    sys.exit("lexsync: %s needs a value." % name)
                position += 1
                value = argv[position]
            given[name[2:]] = value
        position += 1
    return given


def ask_launch():
    """The participant number and the version, from a dialogue at start-up."""
    # Imported here, so a run launched with arguments needs no GUI toolkit.
    from psychopy import gui
    answers = {"participant": "", "version": ""}
    dlg = gui.DlgFromDict(answers, title="lexsync: zh_freqcontrast")
    if not dlg.OK:
        # Cancel ends the run, as it does in PsychoPy's own experiments.
        core.quit()
        sys.exit(0)
    return answers


def positive_integer(text, what):
    """A participant number, a version or a list, as a whole number from 1."""
    text = str(text).strip()
    if not re.match(r"\A[0-9]+\Z", text) or int(text) < 1:
        sys.exit("lexsync: the %s must be a whole number from 1, not '%s'." % (what, text))
    return int(text)


def choose_version(given):
    """The version this run presents, and the participant number if one was given.

    A version named outright wins: ``--version K``, or ``--list K`` when the versions
    do not span several replicates. Otherwise participant p runs version
    ((p - 1) mod V) + 1, and a design with one version needs neither.
    """
    n = len(VERSIONS)
    if not n:
        sys.exit("lexsync: the conditions file holds no trials.")
    text = {key: str(given.get(key) or "").strip()
            for key in ("participant", "version", "list")}
    participant = (positive_integer(text["participant"], "participant number")
                   if text["participant"] else None)
    if text["version"]:
        wanted = positive_integer(text["version"], "version")
        if wanted > n:
            sys.exit("lexsync: version %d was asked for, but this experiment has %s."
                     % (wanted, "version 1 only" if n == 1 else "versions 1 to %d" % n))
        chosen = VERSIONS[wanted - 1]
    elif text["list"]:
        if len({v["replicate"] for v in VERSIONS}) > 1:
            sys.exit("lexsync: this experiment's versions span several replicates, so a "
                     "list does not name one. Give --version (1 to %d) instead." % n)
        wanted = positive_integer(text["list"], "list")
        named = [v for v in VERSIONS if v["list"] == wanted]
        if not named:
            sys.exit("lexsync: there is no list %d. This experiment has lists %s."
                     % (wanted, ", ".join(str(v["list"]) for v in VERSIONS)))
        chosen = named[0]
    elif participant is not None:
        chosen = VERSIONS[(participant - 1) % n]
    elif n == 1:
        chosen = VERSIONS[0]
    else:
        sys.exit("lexsync: give a participant number, or a version from 1 to %d." % n)
    return chosen, participant


def resolve_trigger(spec, trial):
    """A trigger spec is an int literal or '@column' naming a loop-table code."""
    if spec is None or spec == "":
        return None
    if isinstance(spec, str) and spec.startswith("@"):
        return int(trial[spec[1:]])
    return int(spec)


def measure_refresh_hz(win):
    """The display's actual refresh rate, measured; falls back to the declared one.

    Durations are authored in milliseconds, so the number of flips that realises
    one depends on the monitor actually in use. Measuring here is what lets the
    same design present the same duration at 60, 120 or 144 Hz. An implausible or
    failed measurement falls back rather than silently mistiming the experiment.
    """
    try:
        hz = win.getActualFrameRate(nIdentical=10, nMaxFrames=120, nWarmUpFrames=10)
    except Exception:
        hz = None
    if hz is None or not (20.0 < float(hz) < 1000.0):
        print("[lexsync] could not measure the refresh rate; assuming %g Hz"
              % ASSUMED_REFRESH_HZ)
        return float(ASSUMED_REFRESH_HZ)
    return float(hz)


def ms_to_frames(ms, hz):
    """Whole flips covering ``ms`` at ``hz``; never fewer than one.

    Rounding to the nearest flip keeps the realised duration as close to the
    declared one as the display allows. The data file records the flips each event
    took, and a photodiode remains the check on an onset-critical duration.
    """
    return max(1, int(round(float(ms) * float(hz) / 1000.0)))


def trigger_hold_frames(hz):
    """Whole flips the onset code is held for at ``hz``.

    Floored at one flip, so a code is always held across at least one refresh, and
    at the recorder minimum, so a fast display cannot shorten the pulse below what
    the amplifier can register. Expressing the hold in milliseconds is what makes
    that floor meaningful: as a frame count it silently shortened with the refresh.
    """
    ms = max(float(TRIGGER_HOLD_MS), float(MIN_TRIGGER_HOLD_MS))
    return max(1, int(round(ms * float(hz) / 1000.0)))


def new_record():
    """What one event records: the flips it took and the time of its first, and for
    an event that collects a key, the key's name, its reaction time in seconds and
    whether the window closed without one. ``escape`` stops the run."""
    return {"flips": 0, "onset": None, "key": None, "rt": None, "timed_out": None,
            "region_rts": None, "escape": False}


def flip(win, shown):
    """Flip the window for the event being shown, counting the flip and keeping the
    time of the event's first."""
    t = win.flip()
    if not shown["flips"]:
        shown["onset"] = t
    shown["flips"] += 1
    return t


def open_window(win):
    """Open a response window on the next flip: the keyboard's clock is reset and its
    queue cleared on that flip, so a reaction time runs from it and a key pressed
    before it does not count."""
    win.callOnFlip(KEYBOARD.clock.reset)
    win.callOnFlip(KEYBOARD.clearEvents)


def first_key(keys):
    """The first of ``keys`` pressed since the window opened, or None."""
    pressed = KEYBOARD.getKeys(keyList=keys, waitRelease=False)
    return pressed[0] if pressed else None


def wait_for_key(win, shown, stim, keys, deadline):
    """Show ``stim``, or a blank, flip by flip until one of ``keys`` is pressed or
    ``deadline`` seconds have passed on the keyboard clock, and return the key or
    None. A deadline of None waits for a key. The deadline is checked after each flip,
    because a window opened by open_window() resets the clock on its first flip, and
    until then the clock still runs from the window before."""
    while True:
        if stim is not None:
            stim.draw()
        flip(win, shown)
        key = first_key(keys)
        if key is not None:
            return key
        if deadline is not None and KEYBOARD.clock.getTime() >= deadline:
            return None


def collected(shown, key):
    """Record the key a response window collected, or that it closed without one."""
    if key is None:
        shown["timed_out"] = True
    elif key.name == "escape":
        shown["escape"] = True
    else:
        shown.update(key=key.name, rt=key.rt, timed_out=False)
    return shown


def show_frames(win, stim, frames, port, trigger, shown, keys=None):
    """Draw ``stim`` for ``frames`` flips; if a trigger is given, lock it to onset.

    With ``keys``, a response window opens on the onset flip, the keys are polled
    after every flip and the first one ends the stimulus and is returned.
    """
    if trigger is not None:
        win.callOnFlip(port.setData, trigger)
    if keys:
        open_window(win)
    # callOnFlip runs its callback on the NEXT flip, so queueing the reset on this
    # index clears the code one flip later and holds it for exactly
    # TRIGGER_HOLD_FRAMES flip intervals. Queueing on TRIGGER_HOLD_FRAMES itself
    # would hold it for one interval longer than declared, which is what the
    # frame-count version did while documenting otherwise.
    reset_at = TRIGGER_HOLD_FRAMES - 1
    for f in range(frames):
        if stim is not None:
            stim.draw()
        flip(win, shown)
        if trigger is not None and f == reset_at:
            win.callOnFlip(port.setData, 0)
        key = first_key(keys) if keys else None
        if key is not None:
            if trigger is not None and f < reset_at:
                # A key ended the stimulus before the reset was queued, so the code is
                # cleared here, as below.
                port.setData(0)
            return key
    if trigger is not None and frames <= reset_at:
        # The event ends before the reset could be queued, so clear the port here.
        # This one write is not flip-locked, but only the ONSET has to be
        # frame-accurate and it still is; the alternative is leaving the code high
        # into the following event.
        port.setData(0)
    return None


def event_ms(ev, trial):
    """This event's duration in milliseconds for this trial.

    A fixed duration is carried on the event itself; one that varies from trial to
    trial names a loop-table column instead, which is how a jittered interval or a
    per-item stimulus-onset asynchrony reaches the script. The realised value is
    in the conditions file, so the analysis can use it as a regressor.
    """
    if "ms_column" in ev:
        return int(float(trial[ev["ms_column"]]))
    return int(ev.get("ms", 0))


def event_applies(ev, trial):
    """Whether this event runs on this trial.

    An event may name the blocks it belongs to. Feedback during practice and not during
    the main task is the case this exists for: the event list is global to the design, so
    the restriction travels with the event and is applied per trial here.
    """
    blocks = ev.get("blocks")
    if not blocks:
        return True
    return str(trial.get("block", "main")) in [str(b) for b in blocks]


def show_feedback(win, text_stim, ev, trial, response):
    """Tell the participant whether they were right, during practice.

    The item's `answer` column holds the KEY that is correct, so this is a string
    comparison with nothing to look up. No response at all is reported separately from a
    wrong one, because on a timed task they mean different things to a participant.
    """
    correct_key = str(trial.get(ev.get("answer", "answer"), "")).strip()
    if response is None:
        message = ev.get("no_response", "Too slow")
    elif str(response).strip() == correct_key:
        message = ev.get("correct", "Correct")
    else:
        message = ev.get("incorrect", "Incorrect")
    text_stim.text = message
    shown = new_record()
    show_frames(win, text_stim, ms_to_frames(event_ms(ev, trial), REFRESH_HZ), None, None,
                shown)
    return shown


def trial_run(trial):
    """The run of trials a trial belongs to, which a pause separates from the next.

    It is the trial's block, except that a filler belongs to the main trials' run.
    Fillers are interleaved with the main trials so that nothing sets them apart, and a
    pause before and after each one would do just that.
    """
    block = str(trial.get("block", "main"))
    return "main" if block == "filler" else block


def block_break(win, text_stim, upcoming):
    """A pause between blocks, waiting for a key.

    Without it the practice trials run straight into the task and the participant cannot
    tell that the part that counts has begun.
    """
    text_stim.text = ("End of the practice trials.\n\nPress the space bar to begin."
                      if upcoming == "main" else
                      "Press the space bar to continue.")
    text_stim.draw()
    win.flip()
    keys = KEYBOARD.waitKeys(keyList=["space", "escape"], waitRelease=False)
    return "escape" if keys and any(k.name == "escape" for k in keys) else None


def start_gate(win, text):
    """Show the instructions and wait for the space bar before the first trial.

    The participant reads them at their own pace, and the space bar starts the run,
    which also lets the experimenter start it when the participant is ready. Escape
    stops the run before any trial. The instructions get a smaller wrapped stimulus
    of their own, in the word font so that every script they are written in renders.
    """
    stim = visual.TextStim(win, text=text + "\n\nPress the space bar to begin.", height=28,
                           wrapWidth=1000, color="white", font=WORD_FONT)
    stim.draw()
    win.flip()
    keys = KEYBOARD.waitKeys(keyList=["space", "escape"], waitRelease=False)
    return "escape" if keys and any(k.name == "escape" for k in keys) else None


def run_event(win, port, text_stim, ev, trial):
    """Present one event of a trial and return what it recorded (see new_record)."""
    shown = new_record()
    etype = ev["type"]
    if etype in ("fixation", "text", "mask"):
        text_stim.text = trial[ev["field"]] if "field" in ev else ev.get("text", "")
        ms = event_ms(ev, trial)
        trigger = resolve_trigger(ev.get("trigger"), trial)
        respond = ev.get("respond")
        if not respond:
            show_frames(win, text_stim, ms_to_frames(ms, REFRESH_HZ), port, trigger, shown)
            return shown
        # The stimulus collects its own response: the window opens on its onset flip
        # and stays open, on a blank once the stimulus has gone, for its duration and
        # the timeout together.
        keys = list(respond["keys"]) + ["escape"]
        key = show_frames(win, text_stim, ms_to_frames(ms, REFRESH_HZ), port, trigger,
                          shown, keys)
        if key is None:
            key = wait_for_key(win, shown, None, keys, ms / 1000.0 + float(respond["timeout"]))
        return collected(shown, key)
    if etype == "blank":
        show_frames(win, None, ms_to_frames(event_ms(ev, trial), REFRESH_HZ), port, None,
                    shown)
        return shown
    if etype == "region":
        regions = [r for r in trial[ev["field"]].split(ev.get("sep", "|")) if r != ""]
        crit = int(trial.get("critical_region", 0) or 0)
        keys = [ev.get("key", "space"), "escape"]
        rts = []
        for i, region in enumerate(regions, start=1):
            text_stim.text = region
            trig = resolve_trigger(ev.get("crit_trigger"), trial) if i == crit else None
            if trig is not None:
                win.callOnFlip(port.setData, trig)
            # Each region is timed from the flip that shows it.
            open_window(win)
            text_stim.draw()
            flip(win, shown)
            if trig is not None:
                core.wait(INTER_TRIGGER_S)
                port.setData(0)
            key = first_key(keys)
            if key is None:
                key = wait_for_key(win, shown, text_stim, keys, None)
            if key.name == "escape":
                shown["escape"] = True
                return shown
            rts.append(key.rt)
        shown["region_rts"] = rts
        return shown
    if etype in ("response", "question"):
        # A question presents its own prompt; a response draws nothing, so its first
        # flip clears the preceding stimulus, which therefore offsets at its own
        # duration rather than lingering for the whole response window. Either is
        # timed from that flip.
        stim = None
        if etype == "question":
            text_stim.text = trial.get(ev["field"], "")
            stim = text_stim
        keys = list(ev.get("keys", [])) + ["escape"]
        open_window(win)
        return collected(shown, wait_for_key(win, shown, stim, keys,
                                             float(ev.get("timeout", 2.0))))
    return shown


def run_trial(win, port, text_stim, trial):
    """Run one trial's events and return what each recorded, None for an event that
    does not run in the trial's block, or None for the whole trial on escape."""
    records = []
    # The key the latest response or question collected, which feedback scores.
    response = None
    for ev in EVENTS:
        if not event_applies(ev, trial):
            records.append(None)
            continue
        if ev["type"] == "feedback":
            # Handled here, the only place the response is in scope.
            shown = show_feedback(win, text_stim, ev, trial, response)
        else:
            shown = run_event(win, port, text_stim, ev, trial)
        records.append(shown)
        if shown["escape"]:
            return None
        if ev["type"] in ("response", "question") or "respond" in ev:
            response = shown["key"]
    return records


def ms_text(seconds):
    """Seconds as milliseconds at one decimal place, or empty for no value."""
    return "" if seconds is None else "%.1f" % (float(seconds) * 1000.0)


def data_columns(trials):
    """The data file's header: the run, the trial's fields and what it recorded."""
    fields = list(trials[0]) if trials else []
    middle = [f for f in fields if f not in LEADING_COLUMNS and f not in CODE_COLUMNS]
    codes = [c for c in CODE_COLUMNS if c != "answer" or c in fields]
    return LEADING_COLUMNS + middle + codes + MEASURE_COLUMNS


def trial_row(trial, version, participant, records):
    """One trial's row of the data file."""
    row = dict(trial)
    row.update(participant="" if participant is None else participant,
               version=version["version"], replicate=version["replicate"],
               list=version["list"], block=trial.get("block", ""))
    response = question = None
    rts = []
    for ev, shown in zip(EVENTS, records):
        if shown is None:
            continue
        if ev["type"] == "response" or "respond" in ev:
            response = shown
        elif ev["type"] == "question":
            question = shown
        elif ev["type"] == "region":
            rts += shown["region_rts"] or []
    if response is not None:
        row.update(response=response["key"] or "", rt_ms=ms_text(response["rt"]),
                   timed_out=1 if response["timed_out"] else 0)
    if question is not None:
        row.update(question_response=question["key"] or "",
                   question_rt_ms=ms_text(question["rt"]))
    scored = response if SCORES_RESPONSE else question
    answer = str(trial.get("answer", "")).strip()
    if answer and scored is not None:
        row["correct"] = 1 if str(scored["key"] or "").strip() == answer else 0
    row["region_rts_ms"] = "|".join(ms_text(rt) for rt in rts)
    row["refresh_hz"] = "%.2f" % REFRESH_HZ
    row["event_flips"] = "|".join("" if s is None else str(s["flips"]) for s in records)
    onsets = [s["onset"] for s in records if s is not None and s["onset"] is not None]
    row["event_onsets_ms"] = "|".join(
        "" if s is None or s["onset"] is None else ms_text(s["onset"] - onsets[0])
        for s in records)
    return row


def open_data_file(participant, version):
    """A new data file in DATA_DIR, never one an earlier run wrote, and its path."""
    os.makedirs(DATA_DIR, exist_ok=True)
    stem = "%s%s_v%d_%s" % (DATA_STEM, "" if participant is None else "_p%d" % participant,
                            version["version"], time.strftime("%Y%m%d-%H%M%S"))
    for n in itertools.count(1):
        path = os.path.join(DATA_DIR, stem + ("" if n == 1 else "_%d" % n) + ".csv")
        try:
            return path, open(path, "x", newline="", encoding="utf-8")
        except FileExistsError:
            continue


def main():
    global REFRESH_HZ, TRIGGER_HOLD_FRAMES, KEYBOARD
    given = launch_arguments(sys.argv[1:])
    if not given:
        given = ask_launch()
    version, participant = choose_version(given)
    trials = version_rows(load_trials(CONDITIONS_FILE), version)
    if not trials:
        sys.exit("lexsync: version %d holds no trials in %s."
                 % (version["version"], os.path.basename(CONDITIONS_FILE)))
    print("[lexsync] version %d of %d (replicate %d, list %d): %d trials"
          % (version["version"], len(VERSIONS), version["replicate"], version["list"],
             len(trials)))
    if participant is not None:
        usual = VERSIONS[(participant - 1) % len(VERSIONS)]
        if usual["version"] != version["version"]:
            print("[lexsync] participant %d would normally run version %d, and runs "
                  "version %d as asked." % (participant, usual["version"], version["version"]))
    win = visual.Window(size=(1280, 1024), color="black", units="pix", fullscr=FULLSCREEN)
    REFRESH_HZ = measure_refresh_hz(win)
    TRIGGER_HOLD_FRAMES = trigger_hold_frames(REFRESH_HZ)
    print("[lexsync] presenting at %.2f Hz (%.2f ms per flip); "
          "onset code held %d flips (%.1f ms)"
          % (REFRESH_HZ, 1000.0 / REFRESH_HZ, TRIGGER_HOLD_FRAMES,
             TRIGGER_HOLD_FRAMES * 1000.0 / REFRESH_HZ))
    KEYBOARD = keyboard.Keyboard()
    port = open_port(TRIGGER_ADDRESS)
    text_stim = visual.TextStim(win, text="", height=48, color="white", font=WORD_FONT)
    # The instructions, and the start gate: nothing is recorded until the space bar is
    # pressed, and escape here leaves no data file behind.
    if start_gate(win, INSTRUCTIONS[version["version"] - 1]) == "escape":
        print("[lexsync] stopped at the instructions, and no data file was written.")
        win.close()
        core.quit()
        return
    path, handle = open_data_file(participant, version)
    print("[lexsync] recording to %s" % path)

    win.callOnFlip(port.setData, BLOCK_START_TRIGGER)
    win.flip()
    port.setData(0)

    with handle:
        writer = csv.DictWriter(handle, fieldnames=data_columns(trials),
                                extrasaction="ignore")
        writer.writeheader()
        handle.flush()
        previous_run = None
        for trial in trials:
            # A pause wherever the run of trials changes, which is where the practice
            # trials end. `block` is absent unless the design declares a practice or
            # filler block, in which case every row carries it.
            this_run = trial_run(trial)
            if previous_run is not None and this_run != previous_run:
                if block_break(win, text_stim, this_run) == "escape":
                    break
            previous_run = this_run
            records = run_trial(win, port, text_stim, trial)
            if records is None:
                # Escape: the trial in progress is not written, and the file holds
                # every trial completed before it.
                break
            writer.writerow(trial_row(trial, version, participant, records))
            handle.flush()
    print("[lexsync] data written to %s" % path)

    win.callOnFlip(port.setData, BLOCK_END_TRIGGER)
    win.flip()
    port.setData(0)
    win.close()
    core.quit()


if __name__ == "__main__":
    main()
